class StateManager {
  state;
  listeners = [];
  constructor() {
    this.state = this.loadState();
  }
  loadState() {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      if (data) {
        return JSON.parse(data);
      }
    } catch (e) {
      console.warn("LocalStorage error:", e);
    }
    return {
      score: 0,
      xp: 0,
      streak: 0,
      completedGames: {},
      quizScores: {},
      currentWeek: "hub",
      soundEnabled: true
    };
  }
  save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.state));
    } catch (e) {
      console.warn("LocalStorage save error:", e);
    }
    this.notify();
  }
  getState() {
    return this.state;
  }
  addScore(points, xpPoints = points / 2) {
    this.state.score += points;
    this.state.xp += Math.round(xpPoints);
    this.state.streak += 1;
    this.save();
  }
  resetStreak() {
    this.state.streak = 0;
    this.save();
  }
  markGameComplete(gameId) {
    if (!this.state.completedGames[gameId]) {
      this.state.completedGames[gameId] = true;
      this.addScore(100, 50);
    }
  }
  recordQuizScore(quizId, score, maxScore) {
    this.state.quizScores[quizId] = {
      score,
      maxScore,
      date: new Date().toISOString()
    };
    this.save();
  }
  subscribe(fn) {
    this.listeners.push(fn);
  }
  notify() {
    for (const fn of this.listeners)
      fn();
  }
}
